def unit_of_work(metadata=None, timeout=None):
    def wrapper_(func):
        def inner(*args, **kwargs):
            _metadata = metadata if metadata else {}
            _timeout = timeout if timeout else None
            try:
                transaction = py2neo.Graph().begin_transaction(_metadata, timeout=_timeout)
                result = func(*args, **kwargs)
                transaction.commit()
                return result
            except py2neo.Transaction as e:
                transaction.rollback()
                raise e
        inner._metadata = _metadata
        inner._timeout = _timeout
        return inner
    return wrapper_

