def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def _mru_cache(func, maxsize, typed):
        if maxsize is None or maxsize <= 0:
            raise ValueError('`maxsize` must be positive.')

        cache = dict()
        hits = 0
        misses = 0
        size = 0

        def wrapper(*key):
            nonlocal hits, misses, size
            key = tuple(key)

            if len(key) == 0:
                raise TypeError('`key` must be a non-empty sequence.')

            try:
                value = cache[key]
                hits += 1
                return value
            except KeyError:
                misses += 1
                size += 1
                if size > maxsize:
                    cache.popitem(last=False)
                    size -= 1
                value = func(*key)
                cache[key] = value
                return value

        def hit_rate():
            if hits == 0:
                return None
            return hits / (hits + misses)

        def info():
            return {
                'hits': hits,
                'misses': misses,
                'size': size,
                'hit_rate': hit_rate(),
            }

        return wrapper, info
    return _mru_cache
