def format(sql, params):
    if type(params) == dict:
        # If params is a dict, it's a named parameter style
        params = list(params.values())
    elif type(params) == list:
        # If params is a list, it's an ordinal parameter style
        params = params
    else:
        # If params is none of the above, it's an invalid input
        raise ValueError("Invalid input: params must be a dict or list")

    # Replace each occurrence of ':' with '?' in the sql query
    sql = sql.replace(":", "?")

    # Create a new out-style params dict
    out_style_params = {}
    for i, param in enumerate(params):
        out_style_params[i] = param

    return sql, out_style_params
