    num_objects = 0
    good_objects = 0

    # Iterate over all root nodes in the storage hierarchy
    for root_node in self.hierarchy:
        # Count the number of objects in the current root node
        num_objects += len(root_node.objects)

        # Iterate over all objects in the current root node
        for obj in root_node.objects:
            # If check_digests is True, verify the integrity of the object
            if check_digests:
                if not obj.verify_digest():
                    if show_warnings:
                        print(f"Warning: Object {obj} has invalid digest.")
                    else:
                        continue

            # If validate_objects is True, run the object's validate method
            if validate_objects:
                obj.validate()

            # If the object was found to be valid, increase the count
            if obj.is_valid:
                good_objects += 1

    return num_objects, good_objects
