    """
    Amend the Bugzilla params

    Args:
        params (dict): The original Bugzilla parameters
        bug_ids (list): A list of bug IDs to amend

    Returns:
        dict: The amended Bugzilla parameters with the bug IDs added
    """
    if not isinstance(params, dict):
        raise TypeError("Expected a dict for params, but got {}".format(params))
    if not isinstance(bug_ids, list):
        raise TypeError("Expected a list for bug_ids, but got {}".format(bug_ids))

    amended_params = copy.deepcopy(params)

    if "ids" not in amended_params:
        amended_params["ids"] = []

    for bug_id in bug_ids:
        if bug_id not in amended_params["ids"]:
            amended_params["ids"].append(bug_id)

    return amended_params

