import os

def write_configuration(
    config_filename, rendered_config, mode=0o600, overwrite=False
):
    if not config_filename:
        raise ValueError("config_filename cannot be null")
    if not rendered_config:
        raise ValueError("rendered_config cannot be null")
    if isinstance(mode, str):
        try:
            mode = int(mode, 8)
        except ValueError:
            raise ValueError("Invalid file mode")

    if overwrite or not os.path.exists(config_filename):
        if not os.path.exists(os.path.dirname(config_filename)):
            os.makedirs(os.path.dirname(config_filename))
        with open(config_filename, "w", encoding="utf-8", mode=mode) as f:
