def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    image_id, netloc, use_ssl, use_ssl = None, None, None, None
    if not image_href:
        raise ValueError("Image href cannot be empty")
    try:
        url = urllib.parse.urlparse(image_href)
        if url.scheme == "http":
            use_ssl = False
        elif url.scheme == "https":
            use_ssl = True
        else:
