        if not url.path or url.path == "/":
            raise ValueError("Image href path cannot be empty")
        image_id = url.path.split("/")[-1]
        if not image_id.isdigit():
            raise ValueError("Image ID is not a valid UUID")
        netloc = url.netloc
        if not netloc:
            raise ValueError("Image host cannot be empty")
    except ValueError as e:
        raise ValueError(f"Error parsing image href: {image_href}") from e
    return image_id, netloc, use_ssl

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
