def _parse_image_ref(image_href):
    if not image_href:
        raise ValueError("image_href is not a valid URL")

    parsed_url = urllib.parse.urlparse(image_href)

    if not parsed_url.netloc:
        raise ValueError("image_href is not a valid URL")

    if not parsed_url.path:
        raise ValueError("image_href is not a valid URL")

    image_id = parsed_url.path.split("/")[-1]

    use_ssl = parsed_url.netloc.startswith("https")

    return image_id, parsed_url.netloc, use_ssl
