def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    try:
        if cwd is not None:
            os.chdir(cwd)
        if isinstance(commands, str):
            commands = [commands]
        for command in commands:
            full_args = [command] + [str(arg) for arg in args]
            try:
                completed_proc = subprocess.run(full_args, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
                result = completed_proc.stdout.strip()
            except subprocess.CalledProcessError as e:
                raise CommandError(command=command, output=e.stdout, error=e.stderr, return_code=e.returncode)
            if verbose:
                print("Output for command '{}':".format(command))
                print(result)
            if not hide_stderr:
                print("Errors:", completed_proc.stderr.strip())
            if "error" in result.lower() or "failure" in result.lower():
                raise Exception("Command '{}' failed".format(command))
            return result
    except Exception as e:
        raise RunCommandError(original_exception=e)
