    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be one of 'left', 'right', or 'middle'")
    if len(field_names) != hist.dim:
        raise ValueError("field_names must be a sequence of length equal to the dimension of the histogram")
    if scale is not None and not isinstance(scale, bool):
        raise TypeError("scale must be a boolean")

    # create graph
    graph = Graph(hist.dim, hist.lower_bounds, hist.upper_bounds, field_names=field_names)

    # generate graph points from histogram bins
    for bin in hist:
        value = make_value(bin.content) if make_value is not None else bin.content
        if len(value) != graph.dim:
            raise ValueError("make_value did not return the correct number of values for the dimension of the graph")
        coord = bin.edges[0] if get_coordinate == "left" else bin.edges[1]
        graph.set_point(coord, value)

    # set graph scale
    if scale is True:
        graph.scale = hist.scale

    return graph
