def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not hasattr(hist, "bin_centers"):
        raise ValueError("hist must be a histogram")
    if len(field_names) != hist.ndim:
        raise ValueError("field_names must have the same length as hist.ndim")

    if make_value is None:
        make_value = lambda bin_: bin_.content
    else:
        make_value = lambda bin_: make_value(bin_.content)

    def make_point(bin_, id_):
        if get_coordinate == "left":
            coord = bin_.bin_left
        elif get_coordinate == "right":
            coord = bin_.bin_right
        elif get_coordinate == "middle":
            coord = (bin_.bin_left + bin_.bin_right) / 2
        else:
            raise ValueError("Invalid get_coordinate: " + get_coordinate)
        return (coord, *make_value(bin_))

    points = [make_point(hist.bins[id_], id_) for id_ in range(hist.n_bins)]

    if scale is None:
        scale = hist.scale
    elif scale:
        scale = hist.scale

    return Graph(points, field_names, scale)
