def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid(f"Object {candidate} does not claim to provide interface {iface}")

    if not hasattr(candidate, "__implemented__"):
        raise zope.interface.Invalid(f"Object {candidate} does not define the mandatory attribue `__implemented__`")

    for iface_info in iface.get("interface_info", []):
        if iface_info.name not in candidate.__implemented__:
            raise zope.interface.Invalid(f"Interface info {iface_info.name} is not present in object {candidate}")

        for method_info in iface_info.method_info:
            method_name = method_info.fullname
            if method_name not in dir(candidate):
                raise zope.interface.Invalid(f"Method {method_name} is not present in object {candidate}")

            if method_info.required and not method_info.default:
                method = getattr(candidate, method_name)
                if not callable(method):
                    raise zope.interface.Invalid(f"Method {method_name} in object {candidate} is not callable")

    if vtype and not isinstance(candidate, vtype):
        raise zope.interface.Invalid(f"Object {candidate} does not satisfy required type {vtype.__name__}")

    return True

