        webfinger["subject"] = root.find(".//xrd:subject", ns).text
        webfinger["aliases"] = [alias.text for alias in root.findall(".//xrd:Alias", ns)]
        webfinger["type"] = [type.text for type in root.findall(".//xrd:type", ns)]
        webfinger["properties"] = {"href": root.attrib.get("href"), "src": root.attrib.get("src"), "rel": root.attrib.get("rel"), "type": root.attrib.get("type")}
