def parse_diaspora_webfinger(document: str) -> Dict:
    # Step 1: Check if the document is a JSON string
    try:
        json_data = json.loads(document)
    except json.JSONDecodeError:
        # If the document is not a JSON string, it is an XRD (XML Resource Descriptor)
        xml_data = ElementTree.fromstring(document)
        return parse_xrd(xml_data)

    # Step 2: Parse the JSON data
    data = json_data
    # Step 3: Check if the data contains the required fields
    if "subject" not in data or "links" not in data:
        raise ValueError("Invalid Diaspora webfinger document")
    # Step 4: Return the parsed data
    return data

def parse_xrd(xml_data: ElementTree.Element) -> Dict:
    # Step 1: Find the XRD element
    xrd_element = xml_data.find(".//XRD")
    if xrd_element is None:
        raise ValueError("Invalid XRD document")
    # Step 2: Find the subject element
    subject_element = xrd_element.find(".//Subject")
    if subject_element is None:
        raise ValueError("Invalid XRD document")
    # Step 3: Find the link elements
    link_elements = xrd_element.findall(".//Link")
    if len(link_elements) == 0:
        raise ValueError("Invalid XRD document")
    # Step 4: Return the parsed data
    data = {
        "subject": subject_element.text,
        "links": [
            {
                "rel": link_element.get("rel"),
                "href": link_element.get("href"),
            }
            for link_element in link_elements
        ],
    }
    return data
