def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("Input 'dic' must be a dictionary")
    if not isinstance(key, str):
        raise TypeError("Input 'key' must be a string")
    key_chain = [key]
    for sub_key in keys:
        if not isinstance(sub_key, str):
            raise TypeError("Input 'keys' must be a list of strings")
        key_chain.append(sub_key)
    target_dict = dic
    for sub_key in key_chain[:-1]:
        if sub_key not in target_dict.keys():
            target_dict[sub_key] = {}
        target_dict = target_dict[sub_key]
    target_dict[key_chain[-1]] = val
    return dic

