def _get_conditionally_required_args(self, command_name, options_spec, args):
    # Determine whether the argument is required based on the condition
    # specification in the options spec
    def is_required(arg):
        # Loop through the options spec and find the option corresponding
        # to the argument
        for option in options_spec:
            if option['name'] == arg:
                return option.get('required_when', {}).get(command_name, False)

        # If the option is not found, the argument is not required
        return False

    # Return the list of arguments that are required based on the condition
    return [arg for arg in args if is_required(arg)]

