def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    if not isinstance(type_name, str):
        raise ValueError("type_name must be a string")
    if not isinstance(option_name, str):
        raise ValueError("option_name must be a string")
    if not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dict")

    type_info = spec_option.get("type", {})
    optional = type_info.get("optional", False)
    choices = type_info.get("choices", [])
    multiple = type_info.get("multiple", False)
    default_value = type_info.get("default_value", None)
    arg_type = type_info.get("type", "")
    arg_name = f"{type_name}_{option_name}"
    arg_help = spec_option.get("help", "")

    if optional and multiple:
        raise ValueError("Cannot use both optional and multiple for the same argument")

    if choices and not isinstance(choices, (list, tuple)):
        raise ValueError("choices must be a list or tuple")

    if default_value and multiple:
        raise ValueError("Cannot use default_value with multiple argument")

    if not arg_type:
        raise ValueError("arg_type is required")

    if not arg_name:
        raise ValueError("arg_name is required")

    if not arg_help:
        raise ValueError("arg_help is required")

    return ComplexArgument(subcommand, arg_type, arg_name,
                           optional, multiple, choices, default_value,
                           arg_help)
