def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI."""
    if not ir_workspace or not ir_plugin or not playbook_path:
        raise ValueError("Invalid input! All inputs must be provided")

    # Build command line arguments
    args = [
        ir_plugin.executable,
        playbook_path,
        "-i",
        ir_workspace.host_list]

    if verbose is not None:
        args.extend(["-v", str(verbose)])

    if extra_vars is not None:
        args.extend(["-e", extra_vars])

    if ansible_args is not None:
        args.extend(ansible_args)

    # Execute the command
    try:
        subprocess.check_output(args)
    except subprocess.CalledProcessError as e:
        if e.returncode == 1:
            raise Exception("Playbook failed!") from e
        else:
            raise e
