def _convert_non_cli_args(parser_name, values_dict):
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dict")

    for arg, value in values_dict.items():
        if isinstance(value, str):
            # Try to cast to int
            try:
                values_dict[arg] = int(value)
            except ValueError:
                # Try to cast to float
                try:
                    values_dict[arg] = float(value)
                except ValueError:
                    # If both attempts fail, keep value as str
                    pass
        elif not isinstance(value, bool) and len(value) == 1:
            # Try to cast to bool
            if value.lower() in ('true', 'yes'):
                values_dict[arg] = True
            elif value.lower() in ('false', 'no'):
                values_dict[arg] = False
    return values_dict
