def _convert_non_cli_args(self, parser_name, values_dict):
    required_args = argparse.ArgParser(parser_name, *_REQUIRED_ARGS)
    optional_args = argparse.ArgParser(parser_name, *_OPTIONAL_ARGS)
    for key, value in values_dict.items():
        if key in required_args:
            values_dict[key] = required_args[key].parse(value)
        elif key in optional_args:
            values_dict[key] = optional_args[key].parse(value)
        else:
            raise ValueError("Invalid argument: {}".format(key))
    return values_dict

