public static Dictionary<string, Object> GetPluginSpecFlattenDict(string pluginDir)
{
    Dictionary<string, Object> pluginSpecFlattenDict = null;

    try
    {
        if (!Directory.Exists(pluginDir))
        {
            throw new ArgumentException("The plugin directory does not exist.");
        }

        var pluginSpecFilePath = Path.Combine(pluginDir, "plugin.json");
        if (!File.Exists(pluginSpecFilePath))
        {
            throw new FileNotFoundException("The plugin spec file does not exist.");
        }

        var pluginSpec = JObject.Parse(File.ReadAllText(pluginSpecFilePath));
        pluginSpecFlattenDict = pluginSpec.ToObject<Dictionary<string, Object>>();
    }
    catch (Exception e)
